<template><div class="page-hero"><div class="container"><p class="eyebrow">MEDICAL TEAM</p><h1>医生团队</h1><p>展示医生专业方向与出诊信息，帮助您选择更适合的诊疗服务。</p></div></div><section class="section"><div class="container"><div class="filter-bar"><button :class="{active:!selected}" @click="selected=''">全部医生</button><button v-for="item in categories" :key="item.id" :class="{active:selected===item.id}" @click="selected=item.id">{{item.name}}</button></div><div v-if="loading" class="state-card">正在加载医生团队…</div><div v-else class="doctor-grid doctors-page-grid"><RouterLink v-for="doctor in filtered" :key="doctor.id" :to="`/doctors/${doctor.id}`" class="doctor-card"><div class="doctor-photo"><img v-if="doctor.avatar" :src="doctor.avatar" :alt="`${doctor.name}${doctor.title}`" loading="lazy" /><span v-else class="doctor-initial">{{doctor.name.slice(0,1)}}</span></div><div class="doctor-info"><p>{{doctor.departments?.map(d=>d.name).join(' · ') || doctor.department?.name}}</p><h2>{{doctor.name}} <small>{{doctor.title}}</small></h2><span>{{doctor.displayText || doctor.specialty}}</span><b>查看医生详情 →</b></div></RouterLink></div></div></section></template>
<script setup lang="ts">import { computed,onMounted,ref } from 'vue';import { RouterLink } from 'vue-router';import { Doctor,websiteApi } from '../api';import { useSite } from '../site';const {state}=useSite();const doctors=ref<Doctor[]>([]),loading=ref(true),selected=ref('');const categories=computed(()=>state.data?.categories||[]);const filtered=computed(()=>selected.value?doctors.value.filter(d=>(d.departments||[d.department].filter(Boolean)).some(item=>item?.id===selected.value)):doctors.value);onMounted(async()=>{try{doctors.value=await websiteApi.doctors();}finally{loading.value=false;}});</script>
